import json

def is_vertical_symmetric(grid):
    h, w = len(grid), len(grid[0])
    for c in range(w // 2 + 1):
        for r in range(h):
            if grid[r][c] != grid[r][w - 1 - c]:
                return False
    return True

def is_horizontal_symmetric(grid):
    h, w = len(grid), len(grid[0])
    for r in range(h // 2 + 1):
        for c in range(w):
            if grid[r][c] != grid[h - 1 - r][c]:
                return False
    return True

for name, demo in demos.items():
    input_grid = demo["input"]
    is_v = is_vertical_symmetric(input_grid)
    is_h = is_horizontal_symmetric(input_grid)
    print(f"{name}: vertical_sym={is_v}, horizontal_sym={is_h}")

# Find connected non-zero components
def connected_components(grid):
    h, w = len(grid), len(grid[0])
    visited = [[False]*w for _ in range(h)]
    components = []

    def dfs(r, c, comp):
        if r < 0 or r >= h or c < 0 or c >= w or visited[r][c] or grid[r][c] == 0:
            return
        visited[r][c] = True
        comp.append((r, c, grid[r][c]))
        for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
            dfs(r+dr, c+dc, comp)

    for r in range(h):
        for c in range(w):
            if grid[r][c] != 0 and not visited[r][c]:
                comp = []
                dfs(r, c, comp)
                components.append(comp)
    return components

for name, demo in demos.items():
    input_grid = demo["input"]
    comps = connected_components(input_grid)
    print(f"{name}: {len(comps)} components")
    for i, comp in enumerate(comps):
        vals = set(v for _, _, v in comp)
        print(f"  Component {i}: size={len(comp)}, vals={vals}")

