# Check relative positions of components
for name, demo in demos.items():
    input_grid = demo["input"]
    height, width = len(input_grid), len(input_grid[0])

    # Find bounding boxes of each component
    components_info = []
    for r in range(height):
        for c in range(width):
            if input_grid[r][c] != 0:
                components_info.append(('input', r, c))

    # Simple occupancy grid per row/col
    row_occupied = [set() for _ in range(height)]
    col_occupied = [set() for _ in range(width)]
    for r in range(height):
        for c in range(width):
            if input_grid[r][c] != 0:
                row_occupied[r].add(c)
                col_occupied[c].add(r)

    # Check if components are mostly on left vs right
    half_width = width // 2
    half_height = height // 2

    # Let me count rows/cols per half
    passthrough_matrix = [[0]*width for _ in range(height)]  # 1 if some cell exists
    for r in range(height):
        for c in range(width):
            if input_grid[r][c] != 0:
                passthrough_matrix[r][c] = 1

    # Check horizontal gaps
    rows_with_gap = []
    for r in range(height):
        vals = row_occupied[r]
        if vals:
            min_c, max_c = min(vals), max(vals)
            if max_c - min_c + 1 < width // 2:  # not spanning full width
                rows_with_gap.append(r)

    # Check vertical gaps
    cols_with_gap = []
    for c in range(width):
        vals = col_occupied[c]
        if vals:
            min_r, max_r = min(vals), max(vals)
            if max_r - min_r + 1 < height // 2:
                cols_with_gap.append(c)

    print(f"{name}:")
    print(f"  rows_with_gap: {len(rows_with_gap)}")
    print(f"  cols_with_gap: {len(cols_with_gap)}")

# Check if adjacent across rows or cols means different fill direction
for name, demo in demos.items():
    input_grid = demo["input"]
    height, width = len(input_grid), len(input_grid[0])

    # For each non-zero cell, check if there's another non-zero cell
    # in the same row but disconnected, or same col but disconnected

    rows_components = [[] for _ in range(height)]  # rows with non-zero cells
    for r in range(height):
        for c in range(width):
            if input_grid[r][c] != 0:
                rows_components[r].append(c)

    cols_components = [[] for _ in range(width)]
    for c in range(width):
        for r in range(height):
            if input_grid[r][c] != 0:
                cols_components[c].append(r)

    # Count how many rows have multiple components (gaps in cols)
    horizontal_gaps = sum(1 for r in rows_components if len(rows_components[r]) > 1 and any(input_grid[r][max(rows_components[r][i], min(rows_components[r][i+1]))-1] == 0 for i in range(len(rows_components[r])-1)))

    vertical_gaps = sum(1 for c in cols_components if len(cols_components[c]) > 1 and any(input_grid[rows_components[max(cols_components[c][j], min(cols_components[c][j+1]))-1]][c] == 0 for j in range(len(cols_components[c])-1)))

    print(f"{name}: horizontal_gap_rows={horizontal_gaps}, vertical_gap_cols={vertical_gaps}")

# Check if adjacent across rows or cols means different fill direction
for name, demo in demos.items():
    input_grid = demo["input"]
    height, width = len(input_grid), len(input_grid[0])

    # For each row, check if there are gaps
    row_has_gap = []
    for r in range(height):
        cols = [c for c in range(width) if input_grid[r][c] != 0]
        if cols:
            # Check if they form continuous block
            continuous = True
            for i in range(1, len(cols)):
                if cols[i] != cols[i-1] + 1:
                    continuous = False
                    break
            row_has_gap.append(continuous)

    # For each col, check if there are gaps  
    col_has_gap = []
    for c in range(width):
        rows = [r for r in range(height) if input_grid[r][c] != 0]
        if rows:
            continuous = True
            for i in range(1, len(rows)):
                if rows[i] != rows[i-1] + 1:
                    continuous = False
                    break
            col_has_gap.append(continuous)

    has_row_gap = any(not c for c in row_has_gap)
    has_col_gap = any(not c for c in col_has_gap)

    print(f"{name}: has_row_gap={has_row_gap}, has_col_gap={has_col_gap}")

def transform(grid):
    height, width = len(grid), len(grid[0])

    # Find connected components
    visited = [[False]*width for _ in range(height)]
    comps = []

    for r in range(height):
        for c in range(width):
            if grid[r][c] != 0 and not visited[r][c]:
                comp = []
                def dfs(r, c):
                    if r < 0 or r >= height or c < 0 or c >= width or visited[r][c] or grid[r][c] == 0:
                        return
                    visited[r][c] = True
                    comp.append((r, c))
                    for dr, dc in [(0,1), (0,-1), (1,0), (-1,0)]:
                        dfs(r+dr, c+dc)
                dfs(r, c)
                comps.append(comp)

    if len(comps) < 2:
        return grid  # No transformation if only one component or less

    # Find bounding boxes
    comp_bounds = []
    for comp in comps:
        rs = [r for r, c in comp]
        cs = [c for r, c in comp]
        comp_bounds.append((min(rs), max(rs), min(cs), max(cs)))

    # Sort by center row
    by_row = sorted(range(len(comp_bounds)), key=lambda i: (comp_bounds[i][0] + comp_bounds[i][1]) // 2)
    # Sort by center col  
    by_col = sorted(range(len(comp_bounds)), key=lambda i: (comp_bounds[i][2] + comp_bounds[i][3]) // 2)

    # Calculate gaps
    row_gap = comp_bounds[by_row[1]][0] - comp_bounds[by_row[0]][1]
    col_gap = comp_bounds[by_col[1]][2] - comp_bounds[by_col[0]][3]

    output = [row[:] for row in grid]

    if row_gap > col_gap and row_gap > 0:
        # Horizontal fill
        fill_row = (comp_bounds[by_row[0]][1] + comp_bounds[by_row[1]][0]) // 2
        for c in range(width):
            output[fill_row][c] = 3
    else:
        # Vertical fill
        fill_col = (comp_bounds[by_col[0]][3] + comp_bounds[by_col[1]][2]) // 2
        for r in range(height):
            output[r][fill_col] = 3

    return output

# Test on all demos
for name, demo in demos.items():
    result = transform(demo["input"])
    match = result == demo["output"]
    print(f"{name}: {'PASS' if match else 'FAIL'}")
    if not match:
